{% if output.output | length < 6000 -%}
<output>
{{ output.output -}}
</output>
{%- else -%}
<warning>
The output of your last command was too long.
Please try a different command that produces less output.
</warning>
{%- set elided_chars = output.output | length - 6000 -%}
<output_head>
{{ output.output[:3000] }}
</output_head>
<elided_chars>
{{ elided_chars }} characters elided
</elided_chars>
<output_tail>
{{ output.output[-3000:] }}
</output_tail>
{%- endif -%}

